const c = $input.item.json;
const fields = c.fields || c;
const name = fields.Name || 'Friend';
const firstName = name.split(' ')[0];
const interests = Array.isArray(fields.Interests) ? fields.Interests.join(', ') : (fields.Interests || 'faith-forward apparel');
const history = fields['Purchase History'] || 'no previous purchases';
const tags = Array.isArray(fields.Tags) ? fields.Tags.join(', ') : (fields.Tags || '');
const email = fields.Email || '';

const prompt = `You are writing a personalized outreach email for Dorothy Dean Designs, a faith-based luxury streetwear brand rooted in Black culture.

Brand voice: grounded, affirming, calm but confident, culturally fluent. Never preachy. Never pushy.

Customer info:
- First name: ${firstName}
- Interests: ${interests}
- Purchase history: ${history}
- Tags: ${tags}

Write a short, warm, personalized outreach email. Rules:
- Address them by first name only
- 3-4 sentences max in the body
- Reference their interests or purchase history naturally (if available)
- End with a soft, no-pressure CTA to explore the LIFT collection at dorothydeandesigns.com
- Do not mention discounts or urgency
- Sign off as Dorothy Dean Designs

Return ONLY valid JSON with exactly these keys: {"subject": "...", "body": "..."}`;

return { json: { ...fields, recordId: c.id || fields.id, contactName: firstName, contactEmail: email, prompt } };

const resp = $input.item.json;
const text = resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0] ? resp.candidates[0].content.parts[0].text : '';
let parsed;
try {
  const match = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : text);
} catch(e) {
  parsed = {
    subject: 'Something special from Dorothy Dean Designs',
    body: 'Hi there,\n\nWe have something just for you in our LIFT collection - pieces designed to affirm who you are becoming.\n\nExplore at dorothydeandesigns.com.\n\nWith purpose,\nDorothy Dean Designs'
  };
}
const prev = $('Build Email Prompt').item.json;
return { json: { ...prev, emailSubject: parsed.subject || 'From Dorothy Dean Designs', emailBody: parsed.body || '' } };
